//! Memoization caches whose shape is picked by the key type.
//!
//! A cache hit should cost as little as the key allows:
//!
//! - [`DenseCache`] for index keys (generated by [`newtype_index!`](crate::newtype_index)): one
//!   slot per index, so a lookup is an array access with no hashing.
//! - [`MapCache`] for arbitrary hashable keys, with the `FxHash` hasher.
//! - [`UnitCache`] for `()`: a single slot.
//!
//! Every cache allocates its whole capacity when it is created and never grows: a key beyond the
//! capacity of a dense cache, or one distinct key too many for a map cache, is a broken limit,
//! which is a programmer error, and it panics.
//!
//! Values are `Copy`, so a hit never clones or bumps a reference count. Large results belong in
//! an arena, and the cache stores the `&'arena T`.
//!
//! [`Cache<K, V>`] names the cache chosen for `K` through [`CacheKey`]:
//!
//! ```
//! use vulcan::cache::{Cache, QueryCache};
//!
//! vulcan::newtype_index! {
//!     /// Identifies a function.
//!     pub struct FnId;
//! }
//!
//! let costs: Cache<FnId, u64> = Cache::<FnId, u64>::with_capacity(1024);
//! let id = FnId::from_u32(7);
//! assert_eq!(costs.get_or_insert_with(id, || 42), 42);
//! assert_eq!(costs.get(id), Some(42));
//! ```

use crate::{
    convert::{u32_from_usize, usize_from_u32},
    index::TypedIndex,
};
use core::{hash::Hash, marker::PhantomData};
use parking_lot::RwLock;
use rustc_hash::{FxBuildHasher, FxHashMap};
use std::sync::OnceLock;

/// A thread-safe memoization cache from `K` to `V`.
pub trait QueryCache<K, V: Copy> {
    /// Creates an empty cache and allocates room for `capacity` values: the number of distinct
    /// keys, which for a dense cache are the indices `0..capacity`.
    fn with_capacity(capacity: u32) -> Self;

    /// Returns the cached value for `key`.
    fn get(&self, key: K) -> Option<V>;

    /// Returns the cached value for `key`, computing and storing it with `compute` on a miss.
    fn get_or_insert_with<F>(&self, key: K, compute: F) -> V
    where
        F: FnOnce() -> V;
}

/// Selects the cheapest cache for a key type.
pub trait CacheKey: Copy {
    /// The cache used for this key type.
    type Cache<V: Copy>: QueryCache<Self, V>;
}

/// The cache selected for key type `K`.
pub type Cache<K, V> = <K as CacheKey>::Cache<V>;

/// Ties a cache to its key type without storing a key.
type KeyMarker<K> = PhantomData<fn() -> K>;

/// One slot per index, allocated when the cache is created.
///
/// Concurrent misses on the same key run `compute` once: other threads wait for the first
/// result.
#[derive(Debug)]
pub struct DenseCache<K, V> {
    /// One slot per key; the number of slots is the capacity, so it is not stored twice.
    slots: Box<[OnceLock<V>]>,
    /// The key type.
    _key: KeyMarker<K>,
}

// A dense cache is a boxed slice and nothing else: its pointer and its length.
const _: () = assert!(
    size_of::<DenseCache<(), u64>>() == 2 * size_of::<usize>(),
    "a dense cache holds only its slots"
);

impl<K: TypedIndex, V: Copy> QueryCache<K, V> for DenseCache<K, V> {
    fn with_capacity(capacity: u32) -> Self {
        let slot_count = usize_from_u32(capacity);
        let mut slot_list = Vec::with_capacity(slot_count);
        slot_list.resize_with(slot_count, OnceLock::new);
        assert_eq!(slot_list.len(), slot_count, "one slot per key");
        // No reallocation: the length equals the capacity, so there is nothing to shrink.
        let slots = slot_list.into_boxed_slice();
        assert!(slots.iter().all(|slot| slot.get().is_none()), "a new cache holds no value");
        Self { slots, _key: PhantomData }
    }

    #[inline]
    #[track_caller]
    fn get(&self, key: K) -> Option<V> {
        let position = key.index();
        assert!(position < self.slots.len(), "key beyond the capacity of the dense cache");
        self.slots[position].get().copied()
    }

    #[inline]
    #[track_caller]
    fn get_or_insert_with<F>(&self, key: K, compute: F) -> V
    where
        F: FnOnce() -> V,
    {
        let position = key.index();
        assert!(position < self.slots.len(), "key beyond the capacity of the dense cache");
        let slot = &self.slots[position];
        let value = *slot.get_or_init(compute);
        assert!(slot.get().is_some(), "the slot is filled after a lookup");
        value
    }
}

/// A hash map behind a read-write lock, allocated for its capacity when it is created.
///
/// Hits take the read lock only. On a concurrent miss `compute` may run on several threads; the
/// first value stored wins, so `compute` must be deterministic.
#[derive(Debug)]
pub struct MapCache<K, V> {
    /// The cached values, allocated with room for `capacity` keys.
    map: RwLock<FxHashMap<K, V>>,
    /// The number of distinct keys the cache may hold, which it never exceeds.
    capacity: u32,
}

impl<K: Hash + Eq, V: Copy> QueryCache<K, V> for MapCache<K, V> {
    fn with_capacity(capacity: u32) -> Self {
        let map = FxHashMap::with_capacity_and_hasher(usize_from_u32(capacity), FxBuildHasher);
        assert!(map.capacity() >= usize_from_u32(capacity), "the allocation covers the capacity");
        assert!(map.is_empty(), "a new cache holds no value");
        Self { map: RwLock::new(map), capacity }
    }

    #[inline]
    fn get(&self, key: K) -> Option<V> {
        let map = self.map.read();
        assert!(u32_from_usize(map.len()) <= self.capacity, "the cache stays within capacity");
        assert!(map.capacity() >= usize_from_u32(self.capacity), "the allocation is kept");
        map.get(&key).copied()
    }

    #[track_caller]
    fn get_or_insert_with<F>(&self, key: K, compute: F) -> V
    where
        F: FnOnce() -> V,
    {
        {
            let map = self.map.read();
            if let Some(&value) = map.get(&key) {
                return value;
            }
        }

        // Computed outside the lock, so a slow `compute` never blocks readers.
        let value = compute();

        let mut map = self.map.write();
        let allocation_before = map.capacity();
        let stored = if let Some(&existing) = map.get(&key) {
            // Another thread stored a value first, and the first value wins.
            existing
        } else {
            assert!(u32_from_usize(map.len()) < self.capacity, "the map cache is full");
            let previous = map.insert(key, value);
            assert!(previous.is_none(), "the key was absent before the insert");
            value
        };
        assert_eq!(map.capacity(), allocation_before, "an insert never reallocates");
        assert!(u32_from_usize(map.len()) <= self.capacity, "the cache stays within capacity");
        stored
    }
}

/// A single slot, for queries without arguments.
#[derive(Debug)]
pub struct UnitCache<V> {
    /// The value of the one key, `()`.
    slot: OnceLock<V>,
}

// A unit cache is its slot and nothing else.
const _: () = assert!(
    size_of::<UnitCache<u64>>() == size_of::<OnceLock<u64>>(),
    "a unit cache holds only its slot"
);

impl<V: Copy> QueryCache<(), V> for UnitCache<V> {
    /// Creates an empty cache for the one key `()`.
    ///
    /// # Panics
    ///
    /// Panics if `capacity` is not one: the unit type has exactly one value.
    #[track_caller]
    fn with_capacity(capacity: u32) -> Self {
        assert_eq!(capacity, 1, "the unit key has exactly one value");
        let slot = OnceLock::new();
        assert!(slot.get().is_none(), "a new cache holds no value");
        Self { slot }
    }

    #[inline]
    fn get(&self, (): ()) -> Option<V> {
        self.slot.get().copied()
    }

    #[inline]
    fn get_or_insert_with<F>(&self, (): (), compute: F) -> V
    where
        F: FnOnce() -> V,
    {
        let value = *self.slot.get_or_init(compute);
        assert!(self.slot.get().is_some(), "the slot is filled after a lookup");
        value
    }
}

impl CacheKey for () {
    type Cache<V: Copy> = UnitCache<V>;
}

/// Selects the map cache for each listed key type.
macro_rules! map_keys {
    ($($key:ty),*) => {$(
        impl CacheKey for $key {
            type Cache<V: Copy> = MapCache<Self, V>;
        }
    )*};
}

map_keys!(bool, char, u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);

impl<First: Hash + Eq + Copy, Second: Hash + Eq + Copy> CacheKey for (First, Second) {
    type Cache<V: Copy> = MapCache<Self, V>;
}

impl<T: ?Sized + Hash + Eq> CacheKey for &'static T {
    type Cache<V: Copy> = MapCache<Self, V>;
}

#[cfg(test)]
mod tests {
    use super::*;

    crate::newtype_index! {
        /// Test key.
        struct NodeId;
    }

    /// Fills a dense cache of capacity four: a miss computes, a hit returns the first value, and
    /// the last key of the domain is cached like the first.
    #[test]
    fn dense_cache_computes_once() {
        let cache: Cache<NodeId, u32> = Cache::<NodeId, u32>::with_capacity(4);
        let key = NodeId::from_u32(2);
        assert_eq!(cache.get(key), None);
        assert_eq!(cache.get_or_insert_with(key, || 10), 10);
        assert_eq!(cache.get_or_insert_with(key, || 99), 10, "second call must hit");
        let first = NodeId::from_u32(0);
        assert_eq!(cache.get_or_insert_with(first, || 3), 3);
        let last = NodeId::from_u32(3);
        assert_eq!(cache.get_or_insert_with(last, || 7), 7);
        assert_eq!(cache.get(last), Some(7));
    }

    /// Inserts the key equal to the capacity, the first key outside the domain, which must panic.
    #[test]
    #[should_panic(expected = "key beyond the capacity of the dense cache")]
    fn dense_cache_rejects_an_insert_beyond_capacity() {
        let cache = DenseCache::<NodeId, u32>::with_capacity(4);
        let _value = cache.get_or_insert_with(NodeId::from_u32(4), || 5);
    }

    /// Looks up the key equal to the capacity, which must panic like an insert does.
    #[test]
    #[should_panic(expected = "key beyond the capacity of the dense cache")]
    fn dense_cache_rejects_a_lookup_beyond_capacity() {
        let cache = DenseCache::<NodeId, u32>::with_capacity(0);
        let _value = cache.get(NodeId::from_u32(0));
    }

    /// Fills a map cache to its capacity: hits return the first value, and a hit on a full cache
    /// still succeeds, since it inserts nothing.
    #[test]
    fn map_cache_fills_to_capacity() {
        type PairCache = Cache<(u32, u32), &'static str>;
        let map = PairCache::with_capacity(2);
        assert_eq!(map.get_or_insert_with((1, 2), || "a"), "a");
        assert_eq!(map.get_or_insert_with((1, 2), || "b"), "a");
        assert_eq!(map.get((3, 4)), None);
        assert_eq!(map.get_or_insert_with((3, 4), || "c"), "c", "the last key that fits");
        assert_eq!(map.get_or_insert_with((1, 2), || "d"), "a", "a hit on a full cache");
    }

    /// Inserts one distinct key more than the capacity, which must panic.
    #[test]
    #[should_panic(expected = "the map cache is full")]
    fn map_cache_rejects_a_key_past_capacity() {
        let map = MapCache::<u32, u32>::with_capacity(1);
        let _first = map.get_or_insert_with(1, || 1);
        let _second = map.get_or_insert_with(2, || 2);
    }

    /// Fills the single slot of a unit cache and checks that it is computed once.
    #[test]
    fn unit_cache_computes_once() {
        let unit: Cache<(), u8> = Cache::<(), u8>::with_capacity(1);
        assert_eq!(unit.get(()), None);
        assert_eq!(unit.get_or_insert_with((), || 1), 1);
        assert_eq!(unit.get_or_insert_with((), || 2), 1);
        assert_eq!(unit.get(()), Some(1));
    }

    /// Creates a unit cache with a capacity of zero, which cannot hold the one key.
    #[test]
    #[should_panic(expected = "the unit key has exactly one value")]
    fn unit_cache_rejects_a_capacity_other_than_one() {
        let _unit = UnitCache::<u8>::with_capacity(0);
    }
}
